import fs from "node:fs";
import { runAgent } from "../src/agent";
import { assertFidelidade, assertRelevancia } from "./asserts";
import { loadBaseline, saveBaseline } from "./baseline";

type Case = { id: string; pergunta: string; gabarito: string; contexto: string };

type Metric = "fidelidade" | "relevancia";

async function runOne(c: Case) {
  const out = await runAgent({ pergunta: c.pergunta, contexto: c.contexto });
  return {
    id: c.id,
    fidelidade: await assertFidelidade(out, c.gabarito, c.contexto),
    relevancia: await assertRelevancia(out, c.pergunta),
  };
}

export async function runRegressionSuite(path: string) {
  const cases: Case[] = parseCases(fs.readFileSync(path, "utf8"));
  const baseline = loadBaseline("regression.baseline.json");
  const results = await Promise.all(cases.map(runOne));
  const report: Record<Metric, number> = { fidelidade: 0, relevancia: 0 };
  for (const m of ["fidelidade", "relevancia"] as Metric[]) {
    const avg = results.reduce((a, r) => a + r[m], 0) / results.length;
    report[m] = avg;
    const drop = baseline[m] - avg;
    if (drop > 0.02) throw new Error(`regresión en ${m}: baseline ${baseline[m]} vs actual ${avg}`);
  }
  return report; // el CI lo consume y decide el gate
